mapper.sql:
select t.* from( select '待处理' validStatus, t.periodProdId, t.periodId, to_char(t.investCycle) investCycle, t.publish_type publishType, t.rateType, t.rateLower, t.rateLimit, t.rate, t.indexId, t.coefficient, t.spreadRate, t.resetType, t.termType, t.baseRule, t.dates startDate, t.dates + t.investCycle endDate, t.p_finprod_id as finprodId, 0 branch, t.effDate from ( select fp.finprod_id periodProdId, '' periodId,/*期次代码*/ fpa.investment_cycle investCycle/*投资周期*/, fbri.publish_type, fbri.rate_type rateType, fbri.rate_lower *100 rateLower, fbri.rate_limit *100 rateLimit, fbri.rate *100 rate, fbri.index_id indexId, fbri.coefficient, fbri.spread_rate *100 spreadRate, fbri.reset_type resetType, fpa.term_type termType, case when fbri.publish_type = #{publishType01} then to_char(fbri.rate_lower *100, 'fm9990.0099999') || '~' || to_char(fbri.rate_limit *100, 'fm9990.0099999') when fbri.rate_type = #{calcType01} then to_char(fbri.rate * 100, 'fm9990.0099999') when fbri.rate_type = #{calcType02} then ite.text ||'*'|| fbri.coefficient ||'+'||to_char(fbri.spread_rate*100,'fm9990.0099999') end as baseRule, fp.p_finprod_id, fp.mdate, days.dates,fbri.EFF_DATE effDate from fin_product fp left join fin_product_add fpa on fp.finprod_id = fpa.finprod_id
inner join PTL_PORTFOLIO_AUTHORITY ppa on fpa.PORTFOLIO_ID = ppa.PORTFOLIO_ID and ppa.USER_ID = #{userId}
left join fin_open_plan fop on fp.p_finprod_id = fop.finprod_id left join fin_base_rule_info fbri on fbri.finprod_id = fp.finprod_id AND fbri.base_rule_type = #{baseRuleType01} AND fbri.branch = 0 left join (SELECT ITEM_CODE id, ITEM_VALUE text FROM SYS_DATADICT_LIST WHERE DICT_CODE = 'SECRATE_DATA' UNION ALL SELECT INDEX_ID id, INDEX_NAME text FROM MST_INDEX_INFO) ite on ite.id = fbri.index_id left join info inf on inf.eff_date = fbri.eff_date and inf.base_rule_id = fbri.base_rule_id, (select to_date(#{platDate},'yyyy-MM-dd') + level -1 as dates from dual connect by to_date(#{platDate},'yyyy-MM-dd') + level -1 <= to_date(#{platDate},'yyyy-MM-dd') + 7 ) days where fpa.deal_mode = #{dealMode10} and fp.p_finprod_id is not null and fop.finprod_id is null
and fpa.term_type != #{termType03}
and days.dates >= fp.VDATE and days.dates + fpa.investment_cycle <= fp.MDATE )t where t.dates <= t.mdate and not exists (select t1.finprod_id from fin_trade_product t1 where t1.finprod_id = t.periodProdId and t1.term = t.investCycle and t1.vdate = t.dates)) t
and t.finprodId in
#{item}
and t.startDate >= to_date(#{startDateBegin},'yyyy-MM-dd')
and t.startDate <= to_date(#{startDateEnd},'yyyy-MM-dd')
and t.endDate >= to_date(#{endDateBegin},'yyyy-MM-dd')
and t.endDate <= to_date(#{endDateEnd},'yyyy-MM-dd')
union all select '待处理' validStatus, t.periodProdId, t.periodId, to_char(t.investCycle) investCycle, t.publishType, t.rateType, t.rateLower, t.rateLimit, t.rate, t.indexId, t.coefficient, t.spreadRate, t.resetType, t.termType, t.baseRule, t.startDate, t.endDate, t.p_finprod_id as finprodId, 0 branch, t.effDate from( select fp.finprod_id periodProdId, '' periodId,/*期次代码*/ fpa.investment_cycle investCycle,/*投资周期*/ fop.open_vdate startDate,/*其次开始日*/ fop.open_vdate + fpa.investment_cycle endDate,/*期次结束日*/ fbri.publish_type publishType, fbri.rate_type rateType, /*利率类型*/ fbri.rate_lower *100 rateLower, fbri.rate_limit *100 rateLimit, fbri.rate *100 rate, fbri.index_id indexId, fbri.coefficient, fbri.spread_rate *100 spreadRate, fbri.reset_type resetType, fpa.term_type termType, case when fbri.publish_type = #{publishType01} then to_char(fbri.rate_lower *100, 'fm9990.0099999') || '~' || to_char(fbri.rate_limit *100, 'fm9990.0099999') when fbri.rate_type = #{calcType01} then to_char(fbri.rate * 100, 'fm9990.0099999') when fbri.rate_type = #{calcType02} then ite.text ||'*'|| fbri.coefficient ||'+'||to_char(fbri.spread_rate*100,'fm9990.0099999') end as baseRule, fp.p_finprod_id, fbri.EFF_DATE effDate from fin_product fp left join fin_product_add fpa on fp.finprod_id = fpa.finprod_id
inner join PTL_PORTFOLIO_AUTHORITY ppa on fpa.PORTFOLIO_ID = ppa.PORTFOLIO_ID and ppa.USER_ID = #{userId}
left join fin_open_plan fop on fp.p_finprod_id = fop.finprod_id left join fin_base_rule_info fbri on fbri.finprod_id = fp.finprod_id AND fbri.base_rule_type = #{baseRuleType01} AND fbri.branch = 0 left join (SELECT ITEM_CODE id, ITEM_VALUE text FROM SYS_DATADICT_LIST WHERE DICT_CODE = 'SECRATE_DATA' UNION ALL SELECT INDEX_ID id, INDEX_NAME text FROM MST_INDEX_INFO) ite on ite.id = fbri.index_id left join info inf on inf.eff_date = fbri.eff_date and inf.base_rule_id = fbri.base_rule_id where fpa.deal_mode = #{dealMode10} and fp.p_finprod_id is not null and not exists ( select t.finprod_id from fin_trade_product t where t.finprod_id = fpa.finprod_id and t.term = fpa.investment_cycle and t.vdate = fop.open_vdate ) and fop.open_vdate >= to_date(#{platDate},'yyyy-MM-dd') and fop.open_vdate <= to_date(#{platDate},'yyyy-MM-dd') + 7 and fop.open_vdate + fpa.investment_cycle <= fp.MDATE
and fpa.term_type != #{termType03}
) t
and t.p_finprod_id in
#{item}
and t.startDate >= to_date(#{startDateBegin},'yyyy-MM-dd')
and t.startDate <= to_date(#{startDateEnd},'yyyy-MM-dd')
and t.endDate >= to_date(#{endDateBegin},'yyyy-MM-dd')
and t.endDate <= to_date(#{endDateEnd},'yyyy-MM-dd')

mapper.select:
with info as ( SELECT MAX(t.eff_date) eff_date, t.base_rule_id FROM fin_base_rule_info t WHERE t.branch = 0 AND t.base_rule_type = '01' AND t.eff_date <= to_date(#{platDate},'yyyy-MM-dd') group by t.base_rule_id ) select * from (
union all
) order by PERIODPRODID , STARTDATE

select fp.finprod_id finprodId, fp.finprod_abbr finprodAbbr, fpa.investment_cycle investCycle, fp.ccy, fpa.term_type termType, fp.profit_type profitType from fin_product fp left join fin_product_add fpa on fpa.finprod_id = fp.finprod_id where 1=1
and fp.finprod_id IN ( select FINPROD_ID from fin_trade_product where branch = #{branch} and PERIOD_ID = #{periodId} )
and fp.p_finprod_id = #{finprodId}

select fin_float_calc_rule_detail.LEV lev, fin_float_calc_rule_detail.base_rule_id baseRuleId, fin_float_calc_rule_detail.coefficient , fin_float_calc_rule_detail.spread_rate * 100 spreadRate, fin_float_calc_rule_detail.charge_ratio * 100 chargeRatio from fin_float_calc_rule_detail ,fin_product,fin_cash_info left join FIN_TRADE_PRODUCT on fin_cash_info.finprod_id = FIN_TRADE_PRODUCT.finprod_id AND fin_cash_info.BRANCH = FIN_TRADE_PRODUCT.BRANCH where fin_float_calc_rule_detail.cash_id = fin_cash_info.cash_id and fin_cash_info.finprod_id = fin_product.finprod_id and fin_cash_info.cash_type_1 = #{cashType1} and fin_cash_info.cash_type_2 = #{cashType2} and fin_float_calc_rule_detail.EFF_DATE = ( select max(t.EFF_DATE) from fin_float_calc_rule_detail t where t.CASH_ID = fin_float_calc_rule_detail.CASH_ID AND T.EFF_DATE <= to_date(#{effDate},'yyyy-MM-dd') )
and fin_cash_info.finprod_id = #{periodProdId}
and FIN_TRADE_PRODUCT.PERIOD_ID = #{periodId}
and fin_cash_info.BRANCH = 0
and fin_cash_info.finprod_type = #{type01} order by lev

select fci.cash_id cashId
	from fin_cash_info fci
	where fci.cash_type_1 = #{cashType1}
	and fci.cash_type_2 = #{cashType2}
	and fci.Branch = #{branch}
	and fci.finprod_id = #{periodProdId}

mapper.delete:
delete from fin_base_rule_info
where FINPROD_ID = #{periodProdId,jdbcType=VARCHAR}
  and BRANCH = #{branch}
  and BASE_RULE_TYPE = #{baseRuleType,jdbcType=VARCHAR}

mapper.select:
select a.eff_date effDate, a.rate_type rateType, a.rate *100 rate, a.index_id indexId, a.index_source indexSource, a.coefficient, a.spread_rate *100 spreadRate, a.reset_type resetType, a.publish_type publishType, a.rate_limit *100 rateLimit, a.rate_lower *100 rateLower from fin_base_rule_info a left join fin_trade_product ftp on a.finprod_id = ftp.FINPROD_ID AND ftp.branch = #{branch} where a.branch = #{branch} and a.base_rule_type = #{BASE_RULE_TYPE} and a.EFF_DATE = to_date(#{effDate}, 'yyyy-MM-dd')
and ftp.period_id = #{periodId}
and a.finprod_id = #{periodProdId}

	select  ftp.FINPROD_ID
      from fin_trade_product ftp
	where ftp.branch = #{branch}

	   and ftp.period_id = #{periodId}

select pm.BUSINESS_DATA businessData
from SYS_DATA_PROCESS_MARK pm
inner join (
select
max(HIS_NO)	       HIS_NO,
WORKFLOW_ID
from SYS_DATA_PROCESS_MARK


		PAGE_ID = #{pageId}


group by  WORKFLOW_ID
) tempHis on  pm.HIS_NO = tempHis.HIS_NO and pm.WORKFLOW_ID = tempHis.WORKFLOW_ID


		pm.status in ('A','U','P')


		and pm.PAGE_ID = #{pageId}


		and pm.BUSINESS_DATA_PK1 = #{businessDataPk1}


		and pm.BUSINESS_DATA_PK2 = #{businessDataPk2}


		and pm.WORKFLOW_ID != #{workflowId}


order by pm.create_time desc
